CREATE TABLE daily_finance_customers (customer_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), customer_name VARCHAR(160) NOT NULL, mobile_number VARCHAR(25), alternate_number VARCHAR(25), address TEXT, reference TEXT, area_id UUID NULL, collector_id UUID NULL, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE daily_finance_accounts (finance_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), customer_id UUID NOT NULL REFERENCES daily_finance_customers(customer_id), finance_date DATE NOT NULL, gross_finance_amount NUMERIC(14,2) NOT NULL CHECK(gross_finance_amount>0), initial_deduction NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK(initial_deduction>=0), net_disbursement NUMERIC(14,2) GENERATED ALWAYS AS (gross_finance_amount-initial_deduction) STORED, agreed_total_payable NUMERIC(14,2) NOT NULL, daily_agreed_due NUMERIC(14,2) NOT NULL, expected_collection_days INTEGER NOT NULL, expected_completion_date DATE, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE daily_finance_payments (payment_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), customer_id UUID NOT NULL REFERENCES daily_finance_customers(customer_id), finance_id UUID NOT NULL REFERENCES daily_finance_accounts(finance_id), collection_date DATE NOT NULL, amount NUMERIC(14,2) NOT NULL CHECK(amount>=0), payment_method VARCHAR(20) NOT NULL DEFAULT 'CASH', notes TEXT, status VARCHAR(20) NOT NULL DEFAULT 'CONFIRMED', created_by UUID NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE daily_finance_expenses (expense_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), expense_date DATE NOT NULL, amount NUMERIC(14,2) NOT NULL CHECK(amount>0), description TEXT NOT NULL, created_by UUID NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE daily_finance_capital_transactions (capital_transaction_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), date DATE NOT NULL, type VARCHAR(20) NOT NULL CHECK(type IN ('CAPITAL_RECEIVED','CAPITAL_RETURNED')), amount NUMERIC(14,2) NOT NULL CHECK(amount>0), description TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE daily_finance_audit_logs (audit_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NULL, action VARCHAR(80) NOT NULL, entity VARCHAR(80) NOT NULL, entity_id UUID NOT NULL, old_value JSONB, new_value JSONB, reason TEXT, timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX idx_df_accounts_customer ON daily_finance_accounts(customer_id,status); CREATE INDEX idx_df_payments_finance_date ON daily_finance_payments(finance_id,collection_date); CREATE INDEX idx_df_payments_customer_date ON daily_finance_payments(customer_id,collection_date); CREATE INDEX idx_df_expenses_date ON daily_finance_expenses(expense_date);
